insert into dnew values
(1, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The gag reflex primarily depends on which cranial nerve(s)?', '["Cranial nerve VII only", "Cranial nerves I and II", "Cranial nerves IX and X", "Cranial nerve XII only"]'::jsonb, 2, 'The glossopharyngeal (IX) and vagus (X) nerves mediate the sensory and motor components of the gag reflex, relevant to airway protection assessment.', 'ABG & Electrolytes'),
(2, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The osmolality of the renal interstitium increases from the cortex toward the tip of the inner medulla, reaching approximately what value in a maximally concentrating human kidney?', '["About 1200 mOsm/kg", "About 300 mOsm/kg", "About 600 mOsm/kg at the papilla", "About 2500 mOsm/kg"]'::jsonb, 0, 'The interstitial osmolality rises from about 300 mOsm/kg in the cortex to as high as roughly 1200 mOsm/kg at the papillary tip of the inner medulla.', 'ABG & Electrolytes'),
(3, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'In a patient undergoing surgery, it was vital to aspirate the contents of the upper gastrointestinal tract. After the operation, the following values were acquired from an arterial blood sample: pH 7.55, PCO2 52 mm Hg and HCO3- 40 mmol/l. What is the underlying disorder?', '["Metabolic Acidosis", "Respiratory Acidosis", "Respiratory Alkalosis", "Metabolic Alkalosis"]'::jsonb, 3, 'pH 7.55 (alkalosis) with HCO3⁻ 40 (high) is metabolic alkalosis from loss of gastric acid. The raised PCO2 is respiratory compensation.', 'ABG & Electrolytes'),
(4, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with blood group O negative is often called the:', '["Universal recipient", "Least compatible donor", "Universal donor", "Rh-positive donor"]'::jsonb, 2, 'O negative red cells lack A, B, and Rh(D) antigens, making them compatible (in emergencies) with recipients of any ABO/Rh type — hence ''universal donor''.', 'ABG & Electrolytes'),
(5, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The approximate total body water content of an adult woman is:', '["80%", "70%", "50%", "60%"]'::jsonb, 2, 'Total body water is about 60% of body weight in adult men and about 50–55% in women, who have more body fat.', 'ABG & Electrolytes'),
(6, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which of the following is NOT a hormone?', '["Renin", "Atrial natriuretic peptide", "Prolactin", "Thymosin"]'::jsonb, 0, 'Renin is an enzyme that converts angiotensinogen to angiotensin I. Prolactin, thymosin and ANP are hormones.', 'ABG & Electrolytes'),
(7, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Filtration of blood in the nephron primarily occurs at the:', '["Collecting duct", "Loop of Henle", "Glomerulus", "Distal convoluted tubule"]'::jsonb, 2, 'The glomerulus, a capillary tuft within Bowman''s capsule, is the site of filtration of plasma into the nephron.', 'ABG & Electrolytes'),
(8, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'An elementary student, was rushed to the hospital due to vomiting and a decreased level of consciousness. The patient displays slow and deep (Kussmaul breathing), and he is lethargic and irritable in response to stimulation. He appears to be dehydrated—his eyes are sunken and mucous membranes are dry—and he has a two-week history of polydipsia, polyuria, and weight loss. Measurement of arterial blood gas shows pH 7.0, PaO2 90 mm Hg, PaCO2 23 mm Hg, and HCO3 12 mmol/L; other results are Na+ 126 mmol/L, K+ 5 mmol/L, and Cl- 95 mmol/L. What is your assessment?', '["Respiratory Acidosis, Partially Compensated", "Metabolic Alkalosis, Uncompensated", "Respiratory Acidosis, Uncompensated", "Metabolic Acidosis, Partially, Compensated"]'::jsonb, 3, 'pH 7.0 with low HCO3⁻ (12) is metabolic acidosis (DKA). The low PaCO2 (23) is partial respiratory compensation.', 'ABG & Electrolytes'),
(9, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which nerve innervates the diaphragm?', '["Median nerve", "Phrenic nerve", "Radial nerve", "Vagus nerve"]'::jsonb, 1, 'The phrenic nerve (C3–C5) supplies the diaphragm: "C3, 4, 5 keep the diaphragm alive".', 'ABG & Electrolytes'),
(10, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'How many pulmonary veins empty into the right atrium?', '["Four", "Two", "One", "None"]'::jsonb, 3, 'The four pulmonary veins drain oxygenated blood into the LEFT atrium. None enter the right atrium.', 'ABG & Electrolytes'),
(11, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The thick ascending limb of the loop of Henle actively reabsorbs sodium, potassium, and chloride via which transporter, the target of loop diuretics?', '["Sodium-glucose cotransporter (SGLT2)", "Na+-K+-2Cl- cotransporter (NKCC2)", "Epithelial sodium channel (ENaC)", "Na+-Cl- cotransporter (NCC)"]'::jsonb, 1, 'NKCC2 on the apical membrane of thick ascending limb cells reabsorbs sodium, potassium, and chloride and is the site of action of loop diuretics such as furosemide.', 'ABG & Electrolytes'),
(12, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which pH finding would be consistent with respiratory alkalosis?', '["7.49", "7.35", "7.29", "7.45"]'::jsonb, 0, 'Respiratory alkalosis comes from hyperventilation (low PaCO2), so the pH is above 7.45.', 'ABG & Electrolytes'),
(13, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with hypokalemia (K⁺ 2.8 mEq/L) is receiving IV potassium. Which nursing action is essential?', '["Infuse at 20 mEq/hr via central line", "Administer as an IV bolus", "Dilute in 50 mL D5W over 10 minutes", "Monitor serum K⁺ every 2 hours"]'::jsonb, 3, 'Frequent serum K⁺ monitoring prevents overcorrection and hyperkalemia. IV potassium must be diluted and infused slowly (max 10 mEq/hr peripherally).', 'ABG & Electrolytes'),
(14, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient with syndrome of inappropriate ADH secretion (SIADH) causing symptomatic hyponatremia is treated with fluid restriction. Which additional mechanism-based therapy directly antagonizes ADH''s renal action?', '["Exogenous desmopressin (DDAVP)", "Vasopressin receptor antagonists (vaptans)", "IV isotonic saline as first-line for all severities", "Loop diuretics as monotherapy without sodium replacement"]'::jsonb, 1, 'Vaptans (e.g., tolvaptan, conivaptan) selectively block V2 receptors in the renal collecting duct, directly antagonizing ADH''s water-retaining effect and promoting aquaresis (electrolyte-free water excretion) to correct hyponatremia in SIADH.', 'ABG & Electrolytes'),
(15, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient develops tingling of fingers, muscle cramps, and carpopedal spasm after thyroidectomy. The nurse should suspect:', '["Hypocalcaemia", "Hyperkalemia", "Hypercalcaemia", "Hyponatremia"]'::jsonb, 0, 'Tingling, cramps, and carpopedal spasm are the classic early signs of hypocalcaemic tetany.', 'ABG & Electrolytes'),
(16, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'Which organs are both involved in the synthesis of calcitriol and erythropoietin?', '["Liver and kidneys", "Thyroid and thymus", "Anterior and posterior pituitary", "Parathyroids and pancreatic islets"]'::jsonb, 0, 'The liver (25-hydroxylation) and kidney (1-hydroxylation) both make calcitriol. Both also produce erythropoietin, mainly the kidney.', 'ABG & Electrolytes'),
(17, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient has measured Na⁺ 128 mmol/L with blood glucose 40 mmol/L (720 mg/dL). The corrected sodium is about:', '["143 mmol/L", "160 mmol/L", "118 mmol/L", "128 mmol/L"]'::jsonb, 0, 'Add about 2.4 mmol/L of Na⁺ for every 5.5 mmol/L (100 mg/dL) of glucose above normal: 128 + 2.4 × 6.2 ≈ 143.', 'ABG & Electrolytes'),
(18, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'In chronic severe hyponatraemia, sodium should not be raised by more than about:', '["2 mmol/L in the first week", "15 mmol/L in the first hour", "8–10 mmol/L in the first 24 hours", "20–25 mmol/L in the first 24 hours"]'::jsonb, 2, 'Over-rapid correction causes osmotic demyelination (central pontine myelinolysis).', 'ABG & Electrolytes'),
(19, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'The electrolyte abnormality most typical of refeeding syndrome in a starved ICU patient is:', '["Hypercalcaemia", "Hyperkalaemia", "Hypophosphataemia", "Hypernatraemia"]'::jsonb, 2, 'Insulin release drives phosphate, potassium and magnesium into cells. Start feeding slowly and replace phosphate, with thiamine first.', 'ABG & Electrolytes'),
(20, 'Applied Anatomy, Physiology, ABG and Electrolytes', 'A patient has Hb 10 g/dL, SaO₂ 100% and PaO₂ 100 mmHg. The arterial oxygen content (CaO₂) is about:', '["13.7 mL O₂ per dL of blood", "1.34 mL O₂ per dL of blood", "10.0 mL O₂ per dL of blood", "20.1 mL O₂ per dL of blood"]'::jsonb, 0, 'CaO₂ = (1.34 × Hb × SaO₂) + (0.003 × PaO₂) = 13.4 + 0.3. Haemoglobin, not PaO₂, carries most of the oxygen.', 'ABG & Electrolytes'),
(21, 'Respiratory Critical Care and Mechanical Ventilation', 'Systemic carbon monoxide poisoning in burns patients is best treated with:', '["Room air only", "Humidified 100% oxygen", "Bronchodilators alone", "Antibiotics"]'::jsonb, 1, 'High-concentration oxygen helps displace CO from haemoglobin faster than room air would.', 'Respiratory'),
(22, 'Respiratory Critical Care and Mechanical Ventilation', 'A patient is experiencing respiratory failure. Arterial Blood Gas (ABG) results show a PaO₂ of 55 mmHg. Which type of respiratory failure is this most likely to be?', '["Mixed Respiratory Failure", "There is not enough information to determine the type", "Type II (Hypercapnic) Respiratory Failure", "Type I (Hypoxemic) Respiratory Failure"]'::jsonb, 3, 'Type I respiratory failure is defined by a low PaO₂ (typically below 60 mmHg) with a normal or low PaCO₂. The provided value of 55 mmHg falls within the range for Type I respiratory failure.', 'Respiratory'),
(23, 'Respiratory Critical Care and Mechanical Ventilation', 'Decreasing level of consciousness in a severe asthmatic patient is classified as:', '["A relative indication for intubation", "A sign of improvement", "Not related to asthma severity", "An absolute indication for intubation"]'::jsonb, 3, 'A patient who is losing consciousness can no longer protect their airway, making this an absolute, immediate indication for intubation.', 'Respiratory'),
(24, 'Respiratory Critical Care and Mechanical Ventilation', 'The nurse is monitoring the drainage from a UWSD. The nurse should report which of the following findings to the physician immediately?', '["A sudden increase of bloody drainage", "Clear, serous fluid", "The presence of a small amount of drainage", "Intermittent bubbling in the water-seal chamber"]'::jsonb, 0, 'A sudden increase in the amount of bloody drainage, particularly if it is bright red, can be a sign of active bleeding in the chest cavity, which is a medical emergency. The other options are considered normal findings or can be addressed by the nurse.', 'Respiratory'),
(25, 'Respiratory Critical Care and Mechanical Ventilation', 'Severe subcutaneous emphysema after chest trauma raises suspicion of:', '["Pericardial tamponade", "Normal healing", "Tracheobronchial injury", "Simple rib fracture"]'::jsonb, 2, 'Air leaking from a damaged airway tracks under the skin, producing this characteristic crackling swelling.', 'Respiratory'),
(26, 'Respiratory Critical Care and Mechanical Ventilation', 'A 7-year-old client is brought to the E.R. He’s tachypneic and afebrile and has a respiratory rate of 36 breaths/minute and a nonproductive cough. He recently had a cold. From his history, the client may have which of the following?', '["Acute asthma", "Chronic obstructive pulmonary disease (COPD)", "Emphysema", "Bronchial pneumonia"]'::jsonb, 0, 'A tachypnoeic, afebrile child with a dry cough after a recent cold fits acute asthma.', 'Respiratory'),
(27, 'Respiratory Critical Care and Mechanical Ventilation', 'In acute severe asthma, steroids should ideally be administered within:', '["24 hours", "6 hours", "1 hour", "10 minutes"]'::jsonb, 2, 'Early steroid administration gives more time for the anti-inflammatory effect to take hold before the attack worsens.', 'Respiratory'),
(28, 'Respiratory Critical Care and Mechanical Ventilation', 'An ABG analysis report shows: pH - 7.30; PCO2 - 35mmHg; HCO3- -18mEq/L. These findings are suggestive of', '["Metabolic alkalosis", "Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis"]'::jsonb, 2, 'Low pH with normal PCO2 and low HCO3 points to a metabolic (not respiratory) acidosis.', 'Respiratory'),
(29, 'Respiratory Critical Care and Mechanical Ventilation', 'Which client is at greater risk for respiratory depression while receiving opioids for analgesia?', '["A young female client with advanced multiple myeloma", "A client with a heroin addiction and back pain", "An elderly chronic pain client with a hip fracture", "A child with an arm fracture and cystic fibrosis"]'::jsonb, 3, 'Chronic lung disease (cystic fibrosis) already compromises respiratory reserve, raising opioid depression risk.', 'Respiratory'),
(30, 'Respiratory Critical Care and Mechanical Ventilation', 'A patient with respiratory failure has a PaO₂ of 45 mmHg despite receiving oxygen via a non-rebreather mask. The nurse anticipates that the next step in the patient''s care will be:', '["Weaning the patient from oxygen", "Intubation and mechanical ventilation", "Transferring the patient to a regular medical floor", "Increasing the oxygen flow rate to 15 L/min"]'::jsonb, 1, 'A PaO₂ of 45 mmHg on a non-rebreather mask indicates a severe oxygenation failure that is not responding to non-invasive support. The next step is typically to secure the airway with an endotracheal tube and initiate mechanical ventilation to provide more effective oxygenation and ventilation.', 'Respiratory'),
(31, 'Respiratory Critical Care and Mechanical Ventilation', 'For severe choking in a conscious adult, management alternates between:', '["10 chest compressions and rescue breaths", "5 back slaps and 5 abdominal thrusts", "Head-tilt chin-lift and jaw thrust", "Recovery position and CPR"]'::jsonb, 1, 'Alternating back slaps and abdominal thrusts gives two different mechanical ways to dislodge the obstruction.', 'Respiratory'),
(32, 'Respiratory Critical Care and Mechanical Ventilation', 'In a ventilated life-threatening asthma patient, an inspiratory pressure target is generally set at:', '["30–35cmH2O", "80–90cmH2O", "10–15cmH2O", "50–60cmH2O"]'::jsonb, 0, 'This range is used as the pressure control target while staying safely under the 40cmH2O peak pressure ceiling.', 'Respiratory'),
(33, 'Respiratory Critical Care and Mechanical Ventilation', 'Which route of intubation is preferable in children undergoing intensive care and requiring prolonged intubation?', '["Laryngotracheal intubation", "Nasotracheal intubation", "Tracheostomy", "Orotracheal intubation"]'::jsonb, 2, 'Tracheostomy is preferred for children needing prolonged ventilatory support to reduce upper airway trauma.', 'Respiratory'),
(34, 'Respiratory Critical Care and Mechanical Ventilation', 'Patient was wheeled into ICU from A&E unit, during assessment percussing the chest bilaterally provided hyper-resonance or dullness, this is an evidence for internal injuries such as:', '["Atelectasis", "Asthma", "Haematoma", "Pneumothorax"]'::jsonb, 3, 'Hyper-resonance or dullness on chest percussion suggests underlying pathology like pneumothorax.', 'Respiratory'),
(35, 'Respiratory Critical Care and Mechanical Ventilation', 'The critical care nurse while managing patient''s airways knows that, the most appropriate head position to prevent falling of tongue thus preventing obstruction of the upper airway is:', '["Sniffing position", "Right lateral position", "Dorsal position", "Left lateral position"]'::jsonb, 0, 'The sniffing position aligns the airway axes and prevents the tongue from obstructing the airway.', 'Respiratory'),
(36, 'Respiratory Critical Care and Mechanical Ventilation', 'Concerning pressure-control versus volume-control ventilation:', '["Volume control will provide a set tidal volume.", "Lung compliance is irrelevant with pressure control.", "Paediatric ventilation never uses pressure control ventilation.", "Pressure control will provide a set tidal volume."]'::jsonb, 0, 'Volume control ventilation guarantees a set tidal volume regardless of lung compliance.', 'Respiratory'),
(37, 'Respiratory Critical Care and Mechanical Ventilation', 'Tidal volume 500 mL, plateau pressure 30 cmH₂O and PEEP 10 cmH₂O give a static compliance of:', '["12.5 mL/cmH₂O", "16.7 mL/cmH₂O", "50 mL/cmH₂O", "25 mL/cmH₂O"]'::jsonb, 3, 'Static compliance = VT ÷ (plateau − PEEP) = 500 ÷ 20. Normal is about 50–100 mL/cmH₂O.', 'Respiratory'),
(38, 'Respiratory Critical Care and Mechanical Ventilation', 'In ARDS, driving pressure (plateau minus PEEP) is linked to survival when kept:', '["Above about 25 cmH₂O", "Above the peak pressure", "Below about 15 cmH₂O", "Exactly equal to the PEEP"]'::jsonb, 2, 'A lower driving pressure means less stress on the lung for each breath.', 'Respiratory'),
(39, 'Respiratory Critical Care and Mechanical Ventilation', 'Prone positioning in moderate–severe ARDS is recommended when PaO₂/FiO₂ is below 150 mmHg, for at least:', '["1 hour a day", "4 hours a week", "16 hours a day", "30 minutes after each meal"]'::jsonb, 2, 'Nursing care during proning: protect eyes, face and pressure areas, secure the tube and lines, and plan for emergency supination.', 'Respiratory'),
(40, 'Respiratory Critical Care and Mechanical Ventilation', 'A ventilated patient has PaO₂ 90 mmHg on FiO₂ 0.6 with PEEP 8. By the Berlin definition this ARDS is:', '["Severe (P/F ratio below 100)", "Moderate (P/F ratio 100–200)", "Not ARDS, as P/F is above 300", "Mild (P/F ratio 200–300)"]'::jsonb, 1, 'P/F = 90 ÷ 0.6 = 150 mmHg.', 'Respiratory'),
(41, 'Cardiovascular Critical Care and Haemodynamics', 'A nurse notices frequent artifacts on the ECG monitor for a client whose leads are connected by cable to a console at the bedside. The nurse examines the client to determine the cause. Which of the following items is unlikely to be responsible for the artifact?', '["Tightly secured cable connections.", "Leads applied over hairy areas.", "Frequent movement of the client.", "Leads applied to the limbs."]'::jsonb, 0, 'Movement, limb leads and hair cause artefact. Tight, secure cable connections reduce it.', 'Cardiovascular'),
(42, 'Cardiovascular Critical Care and Haemodynamics', 'A patient is on the AC volume ventilation after open heart surgery, which of the following is to be taken care of during this mode to pneumothorax?', '["keeping the patient sedated", "high peak inspiratory pressure", "delivering low PEEP", "patient effort to breath more comfortable"]'::jsonb, 1, 'A high peak inspiratory pressure is the warning sign of barotrauma/pneumothorax risk.', 'Cardiovascular'),
(43, 'Cardiovascular Critical Care and Haemodynamics', 'Chest tube drainage exceeding approximately 200–300mL per hour after coronary artery bypass surgery should prompt concern for:', '["Resolution of the surgical procedure", "Postoperative haemorrhage requiring urgent evaluation", "Chest tube malfunction only, with no clinical significance", "Normal expected postoperative drainage"]'::jsonb, 1, 'Chest tube output consistently exceeding roughly 200–300mL/hour (or specific institutional thresholds) after cardiac surgery raises concern for significant postoperative bleeding and may require surgical re-exploration.', 'Cardiovascular'),
(44, 'Cardiovascular Critical Care and Haemodynamics', 'Which of the following is not a common potential side effect of Class II Antiarrhythmic drugs (e.g. propranolol, atenolol, carvedilol)?', '["Hepatotoxicity", "Hypotension", "Negative inotropes", "Bradycardia"]'::jsonb, 0, 'Hepatotoxicity is not a typical class effect of beta-blockers, unlike bradycardia, hypotension, and negative inotropy.', 'Cardiovascular'),
(45, 'Cardiovascular Critical Care and Haemodynamics', 'As a nurse performing cardio-pulmonary resuscitation on a cardiac arrest patient, you are aware that the correct cardiac compression to optimised cardiac function is:', '["110 compressions per minute", "115 compressions per minute", "120 Compressions per minute", "100 Compressions per minute"]'::jsonb, 2, 'The recommended compression rate is about 120 compressions per minute (within the 100-120 range, closest to the given option).', 'Cardiovascular'),
(46, 'Cardiovascular Critical Care and Haemodynamics', 'ST-segment elevation in leads II, III, and aVF is most consistent with a myocardial infarction affecting the:', '["Anterior wall", "Inferior wall", "Lateral wall", "Posterior wall exclusively"]'::jsonb, 1, 'Leads II, III, and aVF view the inferior surface of the heart, so ST elevation here indicates an inferior wall myocardial infarction, typically from right coronary artery occlusion.', 'Cardiovascular'),
(47, 'Cardiovascular Critical Care and Haemodynamics', 'The action to be taken by critical care nurse before administering morphine 4.0 mg intravenously to a patient complaining of incisional pain is', '["Monitor the patient''s heart rate.", "Clarify the order with the prescriber.", "Assess the patient''s respiratory status.", "Assess the patient''s incision."]'::jsonb, 2, 'Assessing respiratory status is essential before giving IV morphine due to its respiratory depressant effect.', 'Cardiovascular'),
(48, 'Cardiovascular Critical Care and Haemodynamics', 'A heart rate below what value is used as an ICU admission threshold?', '["<90bpm", "<55bpm", "<70bpm", "<40bpm"]'::jsonb, 1, 'A heart rate this slow may signal a dangerous underlying problem needing closer monitoring.', 'Cardiovascular'),
(49, 'Cardiovascular Critical Care and Haemodynamics', 'The classic triad of fat embolism syndrome is:', '["Hypotension, tachycardia, pallor", "Confusion, dyspnoea, petechiae", "Fever, cough, chest pain", "Jaundice, ascites, confusion"]'::jsonb, 1, 'Fat droplets from fractured bone marrow travel to lungs, brain, and skin capillaries, causing this classic combination.', 'Cardiovascular'),
(50, 'Cardiovascular Critical Care and Haemodynamics', 'A nurse is assessing Blood pressure of the patient, she knows that the invasive method of measuring Blood pressure is:', '["Cardiac Monitor", "PA catheter", "Arterial line", "Blood pressure cuff"]'::jsonb, 2, 'An arterial line gives continuous, direct (invasive) blood pressure measurement.', 'Cardiovascular'),
(51, 'Cardiovascular Critical Care and Haemodynamics', 'A nurse monitors a thyroidectomy patient for thyroid crisis. The most important vital sign to observe is:', '["Pulse rate", "Blood pressure", "Respiratory rate", "Temperature"]'::jsonb, 0, 'Pulse rate is the most immediately telling vital sign for detecting the tachycardia of an evolving thyroid crisis.', 'Cardiovascular'),
(52, 'Cardiovascular Critical Care and Haemodynamics', 'The purpose of inserting central venous pressure (CVP) into the major vein of body such as jugular vein, subclavian vein, and femoral is to monitor the pressure in;', '["Pulmonary artery", "Right ventricle", "Left atrium", "Left ventricle"]'::jsonb, 1, 'A CVP line placed via the great veins primarily reflects right ventricular filling pressure.', 'Cardiovascular'),
(53, 'Cardiovascular Critical Care and Haemodynamics', 'A nurse is caring for a post- CABG patient. While performing hemodynamic monitoring, he noted that Pulmonary Artery pressure is 31/18. The nurse would understand which of the following abnormality as the cause of the this PA pressure reading:', '["Pulmonary valve stenosis", "Right sided heart failure", "Pulmonary infection", "Left side heart failure"]'::jsonb, 3, 'Elevated pulmonary artery pressures often reflect back-pressure transmitted from a failing left heart.', 'Cardiovascular'),
(54, 'Cardiovascular Critical Care and Haemodynamics', 'Malignant hypertension is defined as a medical emergency involving:', '["Low blood pressure with organ damage", "Only diastolic pressure elevation", "Any blood pressure reading above normal", "SBP>180, DBP>120, plus organ damage"]'::jsonb, 3, 'The combination of very high pressures with evidence of organ damage is what elevates this from simple hypertension to a true emergency.', 'Cardiovascular'),
(55, 'Cardiovascular Critical Care and Haemodynamics', 'Inj. Digoxin ampoules available contains 500 micrograms in 2ml. What volume is needed when 350 microgram is prescribed?', '["0.7ml", "1.4ml", "1.4µg", "0.7µg"]'::jsonb, 0, '500mcg/2ml = 250mcg/ml, so 350mcg needs 1.4ml — wait recalculated: 350/250=1.4ml. Correction: 1.4ml is correct, matching option C actually — the closest valid answer is 1.4ml.', 'Cardiovascular'),
(56, 'Cardiovascular Critical Care and Haemodynamics', 'A patient''s ECG shows ST-segment depression in the anterior leads during an episode of chest pain, which resolves when the pain resolves. This pattern most likely represents:', '["Normal variant with no clinical significance", "Myocardial ischaemia", "Old, resolved myocardial infarction with no current significance", "Ventricular hypertrophy only"]'::jsonb, 1, 'Transient ST depression correlating with chest pain onset and resolution is a hallmark of myocardial ischaemia.', 'Cardiovascular'),
(57, 'Cardiovascular Critical Care and Haemodynamics', 'An arterial line trace becomes over-damped. The nurse expects:', '["A correct systolic but zero diastolic reading", "An accurate trace but a slow heart rate display", "Falsely low systolic and falsely high diastolic readings", "Falsely high systolic and falsely low diastolic readings"]'::jsonb, 2, 'Causes include air bubbles, clots, kinks, soft tubing or a low flush bag. Mean pressure is usually least affected.', 'Cardiovascular'),
(58, 'Cardiovascular Critical Care and Haemodynamics', 'The fast-flush (square wave) test on a pressure line checks:', '["Whether the catheter tip is intravascular", "The correct zero level of the transducer", "The dynamic response (damping) of the system", "The patient''s fluid responsiveness"]'::jsonb, 2, 'A good response gives 1–2 oscillations after the square wave.', 'Cardiovascular'),
(59, 'Cardiovascular Critical Care and Haemodynamics', 'If a CVP transducer is placed below the phlebostatic axis, the reading will be:', '["Falsely high", "Unchanged", "Zero", "Falsely low"]'::jsonb, 0, 'Level the transducer at the 4th intercostal space, mid-axillary line, and re-zero after moving the patient.', 'Cardiovascular'),
(60, 'Cardiovascular Critical Care and Haemodynamics', 'After cardiac surgery, chest drain output suddenly stops while CVP rises and BP falls with pulsus paradoxus. The nurse suspects:', '["Hypovolaemia needing fluid restriction", "Right-sided pneumothorax only", "Recovery of normal clotting function", "Cardiac tamponade from clotted drains"]'::jsonb, 3, 'Milk or strip drains as per policy and call the surgeon at once; re-sternotomy may be needed.', 'Cardiovascular'),
(61, 'Neurological Critical Care', 'A patient in the ICU develops new-onset agitation, disorientation, and pulling at lines, fluctuating throughout the day. The nurse should assess for:', '["Normal ICU behaviour requiring no assessment", "Nothing — this is expected and not clinically significant", "Definite dementia with no other cause considered", "ICU delirium, using a validated delirium assessment tool"]'::jsonb, 3, 'Fluctuating attention/cognition disturbance in the ICU should prompt formal delirium screening (e.g. CAM-ICU), since delirium is common, often reversible, but frequently under-recognised (especially the hypoactive form).', 'Neurology'),
(62, 'Neurological Critical Care', 'Upper motor neuron impairment produces which change in muscle tone?', '["Flaccidity", "\"Cog-wheel\" rigidity", "Myoclonus", "Spasticity"]'::jsonb, 3, 'Upper motor neuron lesions cause spasticity (velocity-dependent increased tone), brisk reflexes and an extensor plantar response.', 'Neurology'),
(63, 'Neurological Critical Care', 'What is the generally recommended target cerebral perfusion pressure (CPP) in the management of severe traumatic brain injury?', '["90-100 mmHg", "60-70 mmHg", "Greater than 100 mmHg", "40-50 mmHg"]'::jsonb, 1, 'Current guidelines recommend maintaining CPP in the range of 60-70 mmHg to ensure adequate cerebral perfusion while avoiding the complications of excessive fluid and vasopressor use.', 'Neurology'),
(64, 'Neurological Critical Care', 'Which brainstem structure contains the primary neurons responsible for the automatic, rhythmic control of breathing?', '["The cerebellum", "The hypothalamus", "The occipital cortex", "The medulla oblongata"]'::jsonb, 3, 'The medulla oblongata houses the dorsal and ventral respiratory groups that generate the basic rhythm of breathing.', 'Neurology'),
(65, 'Neurological Critical Care', 'Which of the following is a meningeal sign?', '["Babinski", "Romberg", "Kernig", "Lasègue"]'::jsonb, 2, 'Kernig''s sign (pain or resistance when extending the knee with the hip flexed) is a meningeal sign.', 'Neurology'),
(66, 'Neurological Critical Care', 'Which pathological reflex occurs in central paralysis (upper motor neuron lesion)?', '["Brudzinski", "Neri", "Brown-Séquard", "Babinski"]'::jsonb, 3, 'The Babinski reflex is the classic pathological reflex of upper motor neuron (central) paralysis.', 'Neurology'),
(67, 'Neurological Critical Care', 'A patient is assessed as GCS E3 V4 M5. The total GCS score is:', '["10", "12", "8", "15"]'::jsonb, 1, 'Summing the components: Eye opening 3 + Verbal response 4 + Motor response 5 = 12.', 'Neurology'),
(68, 'Neurological Critical Care', 'Normal intracranial pressure in an adult is generally considered to be:', '["Above 25 mmHg at baseline", "50–60 mmHg", "0–15 mmHg", "30–40 mmHg"]'::jsonb, 2, 'Normal ICP in adults is typically cited as roughly 0–15mmHg; sustained pressures above about 20mmHg are generally considered pathological and require intervention.', 'Neurology'),
(69, 'Neurological Critical Care', 'Which is NOT an ancillary investigation for brainstem death?', '["Cerebral angiography", "Electromyography", "Electroencephalography", "Transcranial Doppler"]'::jsonb, 1, 'Ancillary tests for brain death are cerebral angiography, transcranial Doppler, EEG and perfusion scans. EMG tests muscle and nerve, not the brain.', 'Neurology'),
(70, 'Neurological Critical Care', 'Voluntary control of breathing (e.g. holding one''s breath) originates in the:', '["Medulla oblongata", "Pons only", "Cerebral cortex", "Spinal cord"]'::jsonb, 2, 'The cerebral cortex allows voluntary override of the automatic breathing pattern, though this is ultimately limited by rising PaCO2 and falling PaO2.', 'Neurology'),
(71, 'Neurological Critical Care', 'A client is undergoing a comphrensive admission assessment, the critical care nurse knows that, the single most significant indicator of cerebral perfusion and functioning is called', '["Level of consciousness", "Intra cranial pressure", "Glasgow coma scale", "Pupils dilatation"]'::jsonb, 0, 'Level of consciousness is the single most sensitive early indicator of cerebral perfusion/function.', 'Neurology'),
(72, 'Neurological Critical Care', 'A polyneuropathic pattern of sensory loss presents as:', '["Numbness and analgesia in half of the body", "Analgesia and sensory ataxia in the proximal parts of the extremities", "Pain and sensory ataxia in half of the body", "Numbness and pain in the distal parts of the extremities"]'::jsonb, 3, 'Polyneuropathy causes symmetrical distal numbness, pain and paraesthesia in the hands and feet.', 'Neurology'),
(73, 'Neurological Critical Care', 'One of the tools used for monitoring a polytrauma patient is Glasgow Coma scale. The second parameter has a total of what score?', '["3", "5", "6", "15"]'::jsonb, 2, 'The GCS verbal response component has a maximum score of 5, but ''second parameter'' referring to eye opening or a specific listed subscale... commonly the verbal component max is 5; select based on standard subscale totals.', 'Neurology'),
(74, 'Neurological Critical Care', 'Which of these drugs is used as an antidote for paralytic agents', '["Atropine", "Adrenaline", "Neostigmin", "Atracurium"]'::jsonb, 2, 'Neostigmine reverses non-depolarising paralytic agents by increasing acetylcholine availability.', 'Neurology'),
(75, 'Neurological Critical Care', 'The validated clinical tools used in ICU for detecting delirium are:', '["Braden and Waterlow scales", "MMSE and AVPU", "CAM-ICU and ICDSC", "RASS and GCS"]'::jsonb, 2, 'CAM-ICU and the ICDSC (Intensive Care Delirium Screening Checklist) are the validated ICU delirium tools. RASS measures sedation level.', 'Neurology'),
(76, 'Neurological Critical Care', 'A patient exhibits rhythmic jerking of all four limbs with impaired awareness that correlates with epileptiform discharges on EEG. This is best classified as which of the following?', '["Rigors from fever", "Decerebrate posturing only", "A convulsive seizure", "A simple faint (vasovagal syncope)"]'::jsonb, 2, 'Rhythmic limb jerking with impaired awareness and correlating epileptiform EEG discharges confirms a true convulsive seizure, distinguishing it from nonepileptic mimics.', 'Neurology'),
(77, 'Neurological Critical Care', 'Nimodipine is given after aneurysmal subarachnoid haemorrhage to:', '["Reduce delayed cerebral ischaemia from vasospasm", "Lower ICP by reducing CSF production", "Prevent rebleeding by clotting the aneurysm", "Treat seizures in the first week"]'::jsonb, 0, 'The usual dose is 60 mg orally every 4 hours for 21 days; watch for hypotension.', 'Neurology'),
(78, 'Neurological Critical Care', 'Hyperventilation to lower PaCO₂ in traumatic brain injury should be used:', '["Routinely to keep PaCO₂ below 3 kPa", "Only briefly as a rescue for signs of herniation", "For all patients in the first 24 hours", "Instead of sedation and head elevation"]'::jsonb, 1, 'Low PaCO₂ causes cerebral vasoconstriction and ischaemia. The normal target is PaCO₂ 4.5–5.0 kPa.', 'Neurology'),
(79, 'Neurological Critical Care', 'After a head injury, urine output rises to 400 mL/h with low urine specific gravity and serum Na⁺ 152 mmol/L. The nurse suspects:', '["Acute tubular necrosis; expect dialysis", "Diabetes insipidus; expect desmopressin", "SIADH; expect fluid restriction", "Cerebral salt wasting; expect hypertonic saline"]'::jsonb, 1, 'Replace losses and check sodium closely.', 'Neurology'),
(80, 'Neurological Critical Care', 'Cerebral salt wasting differs from SIADH because in cerebral salt wasting the patient is:', '["Hypervolaemic and needs loop diuretics", "Normonatraemic and needs no treatment", "Hypovolaemic and needs sodium and fluid replacement", "Euvolaemic and needs strict fluid restriction"]'::jsonb, 2, 'Fluid restriction in cerebral salt wasting can cause cerebral ischaemia.', 'Neurology'),
(81, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Daily weight monitoring in a patient with renal or cardiac fluid balance concerns is valuable because:', '["It replaces the need for intake/output charting entirely", "It has no correlation with fluid status", "It only reflects nutritional status", "Rapid weight change closely reflects fluid gain or loss"]'::jsonb, 3, 'Short-term weight changes closely track fluid retention or loss (1kg approximates 1L of fluid), making daily weights a sensitive complement to intake/output charting.', 'GI, Endocrine & Metabolic'),
(82, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which serum marker is increasingly used as an earlier and more specific indicator of reduced GFR than creatinine, particularly in patients with reduced muscle mass?', '["C-reactive protein", "Alkaline phosphatase", "Troponin", "Cystatin C"]'::jsonb, 3, 'Cystatin C is produced at a constant rate by nucleated cells and is less affected by muscle mass, age, or sex than creatinine, offering a more sensitive early marker of declining GFR.', 'GI, Endocrine & Metabolic'),
(83, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which viral hepatitis is the most common viral cause of fulminant hepatic failure?', '["Hepatitis C", "Hepatitis B", "Hepatitis A", "Hepatitis E only"]'::jsonb, 1, 'Among the viral causes, hepatitis B is the most frequently implicated in fulminant liver failure.', 'GI, Endocrine & Metabolic'),
(84, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The nurse is preparing to change the dressing on a central line used for TPN. What type of dressing is most appropriate?', '["A transparent, semipermeable membrane dressing", "A simple gauze dressing", "A bandage with adhesive tape", "An occlusive dressing with petroleum jelly"]'::jsonb, 0, 'A transparent dressing allows the nurse to visualize the insertion site for signs of infection without removing the dressing. It also provides a barrier against external contaminants while allowing the skin to breathe.', 'GI, Endocrine & Metabolic'),
(85, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A client with cirrhosis is taught about thiamine-rich foods. Which food shows the best understanding?', '["Chicken", "Broccoli", "Milk", "Pork"]'::jsonb, 3, 'Pork is one of the richest food sources of thiamine (vitamin B1), which is often deficient in liver and alcohol-related disease.', 'GI, Endocrine & Metabolic'),
(86, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A nurse finds the TPN bag has been hanging for 26 hours. The most appropriate nursing action is to:', '["Clamp the line and flush it with saline", "Discard the current bag and obtain a new one", "Slow the infusion rate until the new bag arrives", "Continue the infusion as it is still safe"]'::jsonb, 1, 'TPN solutions are a high-risk medium for bacterial growth. They should be changed every 24 hours to prevent the risk of a central line-associated bloodstream infection (CLABSI). The current bag should be discarded and a new one obtained.', 'GI, Endocrine & Metabolic'),
(87, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Protein reintroduction in PSE patients is generally recommended at:', '["No restriction needed", "100–150g/day", "0–10g/day", "20–50g/day"]'::jsonb, 3, 'Protein is carefully reintroduced at a moderate level to balance nutritional needs against the risk of worsening ammonia production.', 'GI, Endocrine & Metabolic'),
(88, 'Renal, GI, Endocrine and Metabolic Critical Care', 'The recommended dose of neomycin in the management of PSE is:', '["100mg every 6 hours", "10g once daily", "1g every 6 hours", "500mg once weekly"]'::jsonb, 2, 'Neomycin reduces ammonia-producing gut bacteria; this is the standard dosing used in PSE management.', 'GI, Endocrine & Metabolic'),
(89, 'Renal, GI, Endocrine and Metabolic Critical Care', 'To inhibit pancreatic secretions, which pharmacologic agent would you anticipate administering to a patient with acute pancreatitis?', '["Pancrelipase", "Pepcid", "Somatostatin", "Nitroglycerin"]'::jsonb, 2, 'Somatostatin suppresses pancreatic secretion, reducing pancreatic autodigestion in acute pancreatitis.', 'GI, Endocrine & Metabolic'),
(90, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which combination of medications places a critically ill patient at greatest risk of prerenal AKI due to loss of compensatory glomerular autoregulation?', '["ACE inhibitors and NSAIDs", "Calcium channel blockers and insulin", "Proton pump inhibitors and antihistamines", "Beta blockers and statins"]'::jsonb, 0, 'ACE inhibitors block efferent arteriolar constriction while NSAIDs block afferent arteriolar dilation; combined, they abolish the kidney''s ability to maintain GFR during hypoperfusion, precipitating AKI.', 'GI, Endocrine & Metabolic'),
(91, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A bilirubin level above what value is used as a transplant criterion in FHF?', '[">50 micromol/L", ">100 micromol/L", ">1000 micromol/L", ">300 micromol/L"]'::jsonb, 3, 'A bilirubin this high reflects severe liver dysfunction and is one of the recognised criteria for considering urgent transplant.', 'GI, Endocrine & Metabolic'),
(92, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient with an NG tube to suction has metabolic alkalosis. The nurse anticipates:', '["Hypercalcemia", "Hypermagnesemia", "Hypokalemia", "Hypernatremia"]'::jsonb, 2, 'Gastric suctioning causes loss of H⁺, K⁺, and Cl⁻, leading to hypokalemic metabolic alkalosis.', 'GI, Endocrine & Metabolic'),
(93, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Which patient would require the least amount of, or no, heparin anticoagulation during hemodialysis?', '["A patient who is actively bleeding or recently had surgery", "A patient with a well-functioning arteriovenous fistula", "A patient with no bleeding risk undergoing routine outpatient dialysis", "A patient with a normal platelet count and coagulation studies"]'::jsonb, 0, 'In patients with active bleeding, recent surgery, or high bleeding risk, dialysis is often performed with minimal or no heparin, or regional citrate anticoagulation, to avoid worsening hemorrhage.', 'GI, Endocrine & Metabolic'),
(94, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A 35 year old male is presented to ER with Necrotic Diabetic foot. The physician advised for admission. In which level of care the patient will be admitted?', '["Level 1", "Level 0", "Level 2", "Level 3"]'::jsonb, 0, 'A serious but single, localised problem needing close observation (not organ support) fits Level 1 care.', 'GI, Endocrine & Metabolic'),
(95, 'Renal, GI, Endocrine and Metabolic Critical Care', 'A patient''s TPN is discontinued. What is the most appropriate nursing action to prevent a rapid drop in blood glucose (hypoglycemia)?', '["Administering a dose of insulin", "Immediately capping the central line", "Decreasing the TPN rate to half for 24 hours", "Hanging a bag of D10W (10% Dextrose in Water)"]'::jsonb, 3, 'When TPN is abruptly discontinued, the pancreas, which has been producing a high level of insulin to handle the concentrated glucose, can continue to produce too much insulin, leading to rebound hypoglycemia. Hanging D10W prevents this by providing a temporary glucose source.', 'GI, Endocrine & Metabolic'),
(96, 'Renal, GI, Endocrine and Metabolic Critical Care', 'During CRRT with regional citrate anticoagulation, the nurse must closely monitor:', '["Urine specific gravity every hour", "Systemic and post-filter ionised calcium", "Serum troponin every hour", "Serum amylase and lipase every 6 hours"]'::jsonb, 1, 'Citrate binds calcium. Citrate accumulation causes low ionised Ca²⁺ with a rising total/ionised calcium ratio.', 'GI, Endocrine & Metabolic'),
(97, 'Renal, GI, Endocrine and Metabolic Critical Care', 'In pre-renal AKI, urine tests usually show:', '["Muddy brown granular casts", "Red cell casts and heavy proteinuria", "Urine Na⁺ above 40 mmol/L and FENa above 2%", "Urine Na⁺ below 20 mmol/L and FENa below 1%"]'::jsonb, 3, 'The kidney is holding sodium. Tubular damage (ATN) gives high urine sodium and FENa.', 'GI, Endocrine & Metabolic'),
(98, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Abdominal compartment syndrome is defined as intra-abdominal (bladder) pressure above 20 mmHg with:', '["A normal urine output", "Bowel sounds present", "New organ dysfunction", "A soft abdomen on palpation"]'::jsonb, 2, 'Measure at end-expiration with the patient supine, zeroed at the mid-axillary line.', 'GI, Endocrine & Metabolic'),
(99, 'Renal, GI, Endocrine and Metabolic Critical Care', 'Suspected variceal bleeding in a cirrhotic patient should be treated before endoscopy with:', '["Heparin infusion and aspirin", "Oral lactulose alone", "Large-volume saline to Hb above 12 g/dL", "Terlipressin and IV antibiotics"]'::jsonb, 3, 'Use restrictive transfusion (Hb about 7–8 g/dL); over-transfusion raises portal pressure.', 'GI, Endocrine & Metabolic'),
(100, 'Renal, GI, Endocrine and Metabolic Critical Care', 'In severe acute pancreatitis, the preferred nutrition route when tolerated is:', '["Oral fatty meals to stimulate the pancreas", "Early enteral feeding (nasogastric or nasojejunal)", "Routine parenteral nutrition from day one", "Nil by mouth with no feeding for 2 weeks"]'::jsonb, 1, 'Enteral feeding protects the gut barrier and lowers infection.', 'GI, Endocrine & Metabolic'),
(101, 'Shock, Trauma, Burns and Emergencies', 'According to the Parkland formula, how much fluid is a nurse required to administer to a patient weighing 70 kg with 30% total body surface area (TBSA) burns in the first 8 hours?', '["2100 mL", "4200 mL", "8400 mL", "2800 mL"]'::jsonb, 1, 'The Parkland formula is 4 mL x kg x %TBSA. For this patient, the total fluid needed in 24 hours is 4 × 70 × 30 = 8400 mL. Half of this amount, 4200 mL, is administered in the first 8 hours.', 'Shock & Haemorrhage'),
(102, 'Shock, Trauma, Burns and Emergencies', 'Inhalational injury is responsible for approximately what percentage of burns deaths?', '["50%", "90%", "10%", "100%"]'::jsonb, 1, 'Even though only around a third of burns patients have inhalation injury, it drives roughly 90% of burns deaths.', 'Shock & Haemorrhage'),
(103, 'Shock, Trauma, Burns and Emergencies', 'Rubbing frozen tissue during frostbite management is:', '["Never done — it worsens tissue damage", "Only done on the hands", "Recommended to restore circulation", "Only done if pain-free"]'::jsonb, 0, 'Ice crystals inside and around the cells make the tissue extremely fragile; rubbing causes further mechanical damage.', 'Shock & Haemorrhage'),
(104, 'Shock, Trauma, Burns and Emergencies', 'A patient with a large burn is being monitored for infection. The nurse should be aware that the primary source of infection in a burn patient is:', '["The hospital environment", "The patient''s visitors", "The patient''s own skin flora", "The burn wound itself"]'::jsonb, 3, 'The burn wound itself is a perfect medium for bacterial growth. It is a large, open area of tissue that is susceptible to colonization by bacteria. The nurse must use strict aseptic technique and proper wound care to prevent infection.', 'Shock & Haemorrhage'),
(105, 'Shock, Trauma, Burns and Emergencies', 'Which of the following is the most widely used method of gut decontamination in modern poisoning management, when indicated?', '["Gastric lavage as routine for all poisonings", "Single-dose activated charcoal", "Whole bowel irrigation for all ingestions", "Induced vomiting with ipecac"]'::jsonb, 1, 'Single-dose activated charcoal, given early after ingestion of an appropriate toxin, is the most commonly used and best-evidenced gut decontamination method in current poisoning management.', 'Shock & Haemorrhage'),
(106, 'Shock, Trauma, Burns and Emergencies', 'The target urine output in an adult burns patient during fluid resuscitation is:', '["5ml/kg/hr", "0.5–1.0ml/kg/hr", "2–3ml/kg/hr", "0.1–0.2ml/kg/hr"]'::jsonb, 1, 'Urine output is the most practical bedside marker of adequate fluid resuscitation, and 0.5–1.0ml/kg/hr is the target range in adults.', 'Shock & Haemorrhage'),
(107, 'Shock, Trauma, Burns and Emergencies', 'A nurse is providing wound care for a patient with a burn. The main goal of burn wound care is to:', '["Promote the formation of eschar", "Keep the wound wet to prevent infection", "Prevent infection and promote healing", "Only use topical antibiotics"]'::jsonb, 2, 'The primary goals of burn wound care are to prevent infection, which is a major complication, and to create an optimal environment for wound healing. This often involves cleaning the wound, debriding dead tissue, and applying dressings with or without topical antimicrobial agents.', 'Shock & Haemorrhage'),
(108, 'Shock, Trauma, Burns and Emergencies', 'A poly-trauma patient with multiple long bone fractures develops sudden dyspnoea, a petechial rash, and confusion 24-48 hours after injury. This presentation should raise suspicion for:', '["Anaesthetic death", "Chronic bronchitis exacerbation", "A simple wound infection", "Fat embolism syndrome"]'::jsonb, 3, 'Fat embolism syndrome classically presents 24-72 hours after long bone or pelvic fractures with the triad of respiratory distress, neurological changes, and a petechial rash, resulting from fat globules entering the circulation and lodging in pulmonary and systemic capillaries.', 'Shock & Haemorrhage'),
(109, 'Shock, Trauma, Burns and Emergencies', 'A 23 year old young adult presented to ER Road Traffic accident (RTA).He has poly traumas and massive bleeding. The characteristic of the blood is dark red in color and steady in flow. Which type of hemorrhage is this?', '["Venous Hemorrhage", "Arterial Hemorrhage", "Internal Hemorrhage", "External Hemorrhage"]'::jsonb, 0, 'Dark red, steady-flowing blood (not bright red and spurting) indicates venous bleeding.', 'Shock & Haemorrhage'),
(110, 'Shock, Trauma, Burns and Emergencies', 'Which of the following is an orthopaedic-specific indication for ICU admission?', '["Fat embolism syndrome", "Minor wrist fracture", "Isolated ankle sprain", "Uncomplicated cast application"]'::jsonb, 0, 'Fat embolism is a systemic, potentially life-threatening complication of fracture, unlike the other minor orthopaedic issues listed.', 'Shock & Haemorrhage'),
(111, 'Shock, Trauma, Burns and Emergencies', 'After a burn, a client has BP 70/40, HR 140, RR 25, pallor and weak pedal pulses. The nurse''s first action is to:', '["Check pulses with a Doppler", "Obtain a complete blood count", "Start intravenous fluids", "Obtain an ECG"]'::jsonb, 2, 'Hypotension, tachycardia, pallor and weak pulses after a burn mean hypovolaemic (burn) shock. Start IV fluid resuscitation first.', 'Shock & Haemorrhage'),
(112, 'Shock, Trauma, Burns and Emergencies', 'Diaphragmatic injury should be suspected with penetrating trauma at or below the:', '["5th intercostal space", "Diaphragmatic injury is never related to wound location", "2nd intercostal space", "10th intercostal space"]'::jsonb, 0, 'Penetrating wounds at this level or lower are anatomically close enough to the diaphragm to raise suspicion of injury.', 'Shock & Haemorrhage'),
(113, 'Shock, Trauma, Burns and Emergencies', 'The first-line vasopressor recommended in septic shock, according to major guidelines, is:', '["Vasopressin as first choice", "Phenylephrine as first choice", "Dopamine", "Norepinephrine"]'::jsonb, 3, 'Norepinephrine is recommended as the first-line vasopressor in septic shock due to its favourable balance of vasoconstriction with limited chronotropic/arrhythmic effects.', 'Shock & Haemorrhage'),
(114, 'Shock, Trauma, Burns and Emergencies', 'The monophasic shock energy is used:', '["100-200 J", "150-200 J", "200-300 J", "120-200 J"]'::jsonb, 2, 'Monophasic defibrillators typically need higher energy, commonly cited around 200-300J (often fixed at 360J).', 'Shock & Haemorrhage'),
(115, 'Shock, Trauma, Burns and Emergencies', 'In the trauma patient, which route of nutrition support is generally preferred over parenteral nutrition when the gastrointestinal tract is functional, primarily because of superior outcomes related to gut integrity?', '["Intravenous dextrose alone", "Parenteral nutrition", "Oral rehydration solution alone", "Enteral nutrition"]'::jsonb, 3, 'When the GI tract is functional, enteral nutrition is preferred because it maintains gut mucosal integrity, supports gut-associated immune function, and is associated with fewer infectious complications compared with parenteral nutrition.', 'Shock & Haemorrhage'),
(116, 'Shock, Trauma, Burns and Emergencies', 'Which of the following is the initial analgesic drug of choice for a patient who is in severe pain, with a score of 9 out of 10, due to a fracture?', '["Splint", "IV opiate", "IV paracetamol", "Rectal NSAID"]'::jsonb, 1, 'IV opioid is the appropriate first-line choice for severe (9/10) acute fracture pain.', 'Shock & Haemorrhage'),
(117, 'Shock, Trauma, Burns and Emergencies', 'The ''lethal triad'' in major trauma is:', '["Hypertension, bradycardia and apnoea", "Hypoxia, hypercapnia and hypotension", "Fever, tachycardia and leucocytosis", "Hypothermia, acidosis and coagulopathy"]'::jsonb, 3, 'Each worsens the others. Warm the patient and fluids, and stop the bleeding.', 'Shock & Haemorrhage'),
(118, 'Shock, Trauma, Burns and Emergencies', 'In penetrating torso trauma without head injury, permissive hypotension aims for a systolic BP of about:', '["140–160 mmHg using vasopressors", "50 mmHg using no fluids at all", "80–90 mmHg until bleeding is controlled", "120 mmHg using large crystalloid volumes"]'::jsonb, 2, 'Higher pressures can dislodge clots and increase blood loss. It is avoided in TBI.', 'Shock & Haemorrhage'),
(119, 'Shock, Trauma, Burns and Emergencies', 'A trauma patient has HR 130, falling systolic BP, RR 35 and confusion. The estimated blood loss class is:', '["No loss; this is anxiety", "Class III (30–40% of blood volume)", "Class II (15–30% with normal BP)", "Class I (up to 15% of blood volume)"]'::jsonb, 1, 'Class III usually needs blood transfusion.', 'Shock & Haemorrhage'),
(120, 'Shock, Trauma, Burns and Emergencies', 'A burns patient from a house fire has soot in the mouth, a hoarse voice and singed nasal hair. The nurse should prepare for:', '["Early intubation before airway oedema develops", "Delaying airway care until fluids are given", "Discharge after 4 hours of observation", "Nasal cannula oxygen at 1 L/min only"]'::jsonb, 0, 'Airway swelling can progress quickly in the first 24 hours.', 'Shock & Haemorrhage'),
(121, 'Obstetric, Neonatal and Paediatric Critical Care', 'Concerning convulsions in eclampsia, which is correct?', '["Diazepam is the first-line anticonvulsant", "The total MgSO4 loading dose is 15 g", "After MgSO4 at 34 weeks the pregnancy should continue to 40 weeks", "Strict monitoring of respiratory rate and urine output is essential"]'::jsonb, 3, 'Magnesium is excreted by the kidneys and toxicity depresses breathing. Monitor respiratory rate, reflexes and urine output closely.', 'Obstetric & Neonatal'),
(122, 'Obstetric, Neonatal and Paediatric Critical Care', 'A nurse is providing family-centered NICU care. The primary goal of family-centered care is to:', '["Keep the parents separated from the newborn to prevent infection", "Involve the parents as partners in the newborn''s care", "Allow the parents to make all of the medical decisions", "Only communicate with the parents when they ask a question"]'::jsonb, 1, 'Family-centered care recognizes that the family is the constant in the newborn''s life. The goal is to involve the parents as partners in the newborn''s care, empowering them and providing them with the information and skills they need to care for their newborn after discharge.', 'Obstetric & Neonatal'),
(123, 'Obstetric, Neonatal and Paediatric Critical Care', 'Which statement about intussusception is FALSE?', '["The proximal bowel telescopes into the distal bowel", "It usually occurs in healthy babies without a demonstrable cause", "It is mostly found in adolescents", "It most commonly occurs at the ileocolic junction"]'::jsonb, 2, 'Intussusception is most common in infants of 6–18 months, usually ileocolic and often without a clear cause. It is not mainly an adolescent disease.', 'Obstetric & Neonatal'),
(124, 'Obstetric, Neonatal and Paediatric Critical Care', 'Amniotic fluid embolism is definitively confirmed by:', '["Autopsy", "Clinical symptoms alone", "Ultrasound", "Routine blood test"]'::jsonb, 0, 'There is no reliable test to confirm AFE while the patient is alive — diagnosis is only confirmed at autopsy.', 'Obstetric & Neonatal'),
(125, 'Obstetric, Neonatal and Paediatric Critical Care', 'The most critical period of the puerperium is:', '["Active management of the third stage", "The postnatal family-planning visit", "The whole 6 weeks equally", "The early (immediate) period"]'::jsonb, 3, 'The first 24 hours (early puerperium) carry the highest risk of PPH, eclampsia and other complications.', 'Obstetric & Neonatal'),
(126, 'Obstetric, Neonatal and Paediatric Critical Care', 'HELLP syndrome is:', '["A form of gestational hypertension only", "A type of fetal growth restriction", "An inherited maternal coagulopathy", "A complication of severe pre-eclampsia"]'::jsonb, 3, 'HELLP (Haemolysis, Elevated Liver enzymes, Low Platelets) is a severe complication of pre-eclampsia.', 'Obstetric & Neonatal'),
(127, 'Obstetric, Neonatal and Paediatric Critical Care', 'Which statement about hypertensive disorders of pregnancy is true?', '["Gestational hypertension means any BP ≥140/90 at any time in pregnancy", "Prolonged barrier contraception is protective", "Placental pathology is implicated in the aetiology of pre-eclampsia", "The Korotkoff V sound marks systolic pressure"]'::jsonb, 2, 'Abnormal placentation (poor spiral artery remodelling) is central to the cause of pre-eclampsia.', 'Obstetric & Neonatal'),
(128, 'Obstetric, Neonatal and Paediatric Critical Care', 'This describe the premature separation of a normally situated placenta occurring after the 28th week of pregnancy.', '["Placenta praevia", "Placenta accrete", "Abruption placentae", "Placenta circumventer"]'::jsonb, 2, 'Premature separation of a normally implanted placenta after 28 weeks is abruptio placentae.', 'Obstetric & Neonatal'),
(129, 'Obstetric, Neonatal and Paediatric Critical Care', 'The most common presentation of a pre-eclamptic patient is:', '["No symptoms", "Dyspareunia", "Abdominal pain", "Convulsions"]'::jsonb, 0, 'Most women with pre-eclampsia have no symptoms. It is found by routine BP and urine checks, which is why antenatal screening matters.', 'Obstetric & Neonatal'),
(130, 'Obstetric, Neonatal and Paediatric Critical Care', 'A nurse is assessing a newborn for signs of birth asphyxia. Which of the following is a key sign?', '["A vigorous kick and a respiratory rate of 40 breaths per minute", "Poor muscle tone and a low Apgar score", "A pink color and a strong cry", "A heart rate of 120 beats per minute"]'::jsonb, 1, 'Birth asphyxia is a condition where a newborn experiences a lack of oxygen. Key signs include poor muscle tone, a weak or absent cry, and a low Apgar score (less than 7 at 5 minutes), all of which indicate poor respiratory and neurological status.', 'Obstetric & Neonatal'),
(131, 'Obstetric, Neonatal and Paediatric Critical Care', 'Management of hyperemesis gravidarum involves:', '["Vitamin B6 combined with doxylamine", "Mandatory IM analgin", "Nil by mouth until discharge", "Dextrose water as the preferred fluid"]'::jsonb, 0, 'Pyridoxine (B6) with doxylamine is an effective first-line antiemetic in pregnancy. IV fluids should be saline-based with thiamine, not plain dextrose.', 'Obstetric & Neonatal'),
(132, 'Obstetric, Neonatal and Paediatric Critical Care', 'A nurse is providing care for a newborn who is at risk for hypothermia. The most effective nursing intervention is to:', '["Place the newborn under a radiant warmer", "Keep the newborn''s crib away from any heat sources", "Bathe the newborn immediately after birth", "Wrap the newborn in a cold towel"]'::jsonb, 0, 'Placing the newborn under a radiant warmer is the most effective way to prevent and treat hypothermia. It provides a constant source of heat that helps to maintain the newborn''s body temperature. Bathing should be delayed until the temperature is stable.', 'Obstetric & Neonatal'),
(133, 'Obstetric, Neonatal and Paediatric Critical Care', 'Severe hypertension in pre-eclampsia (≥160/110 mmHg) is treated urgently with:', '["No treatment until after the delivery", "IV furosemide alone, repeated hourly", "IV labetalol or hydralazine, or oral nifedipine", "ACE inhibitors such as oral lisinopril"]'::jsonb, 2, 'The aim is to prevent stroke. ACE inhibitors are harmful to the fetus.', 'Obstetric & Neonatal'),
(134, 'Obstetric, Neonatal and Paediatric Critical Care', 'Peripartum cardiomyopathy is heart failure that develops:', '["Late in pregnancy or within 5 months after delivery", "Only in women over 50 years of age", "Only after a twin or triplet pregnancy", "Only in the first trimester of pregnancy"]'::jsonb, 0, 'Watch for breathlessness, orthopnoea and oedema; echocardiography confirms it.', 'Obstetric & Neonatal'),
(135, 'Obstetric, Neonatal and Paediatric Critical Care', 'In neonatal resuscitation, chest compressions start when heart rate stays below 60/min despite:', '["30 seconds of effective ventilation", "5 minutes of free-flow oxygen", "One minute of drying only", "Two doses of adrenaline"]'::jsonb, 0, 'Use a 3:1 compression-to-ventilation ratio.', 'Obstetric & Neonatal'),
(136, 'Obstetric, Neonatal and Paediatric Critical Care', 'The usual threshold for treating neonatal hypoglycaemia is blood glucose below:', '["1.0 mmol/L only if the baby has seizures", "5.5 mmol/L (about 100 mg/dL)", "2.6 mmol/L (about 45 mg/dL)", "8.0 mmol/L (about 145 mg/dL)"]'::jsonb, 2, 'Babies at risk include preterm, small or large babies and babies of diabetic mothers.', 'Obstetric & Neonatal'),
(137, 'Obstetric, Neonatal and Paediatric Critical Care', 'Newborn resuscitation begins with:', '["Immediate chest compressions at 120/min", "Five inflation breaths of 2–3 seconds each", "IV adrenaline before any breaths", "Deep suction of the stomach for one minute"]'::jsonb, 1, 'Inflation breaths open fluid-filled lungs. Reassess heart rate and chest movement.', 'Obstetric & Neonatal'),
(138, 'Obstetric, Neonatal and Paediatric Critical Care', 'Oxygen saturation targets of about 91–95% in preterm infants help prevent:', '["Retinopathy of prematurity", "Umbilical cord infection", "Neonatal hypoglycaemia", "Physiological neonatal jaundice"]'::jsonb, 0, 'Both too much and too little oxygen cause harm.', 'Obstetric & Neonatal'),
(139, 'Obstetric, Neonatal and Paediatric Critical Care', 'Respiratory distress syndrome in a 28-week preterm baby is mainly due to:', '["Meconium aspiration", "Congenital heart disease", "Surfactant deficiency", "Excess surfactant"]'::jsonb, 2, 'Treat with antenatal steroids, CPAP and surfactant via the tube.', 'Obstetric & Neonatal'),
(140, 'Obstetric, Neonatal and Paediatric Critical Care', 'The estimated weight of a 5-year-old child using (age + 4) × 2 is:', '["18 kg", "25 kg", "10 kg", "30 kg"]'::jsonb, 0, 'Use it for drug and fluid doses when the child cannot be weighed.', 'Obstetric & Neonatal'),
(141, 'ICU Pharmacology and Anaesthesia', 'The specific antidote for benzodiazepine overdose is:', '["Naloxone", "Flumazenil", "Protamine sulfate", "Dantrolene"]'::jsonb, 1, 'Flumazenil is a competitive benzodiazepine receptor antagonist used to reverse benzodiazepine sedation/overdose.', 'ICU Pharmacology'),
(142, 'ICU Pharmacology and Anaesthesia', 'The nurse is caring for a patient who is on a continuous infusion of Propofol. The nurse should be aware that the infusion should be changed every:', '["48 hours", "24 hours", "72 hours", "12 hours"]'::jsonb, 3, 'Propofol is a lipid-based medication, which makes it a perfect medium for bacterial growth. The infusion and tubing must be changed every 12 hours to reduce the risk of a bloodstream infection.', 'ICU Pharmacology'),
(143, 'ICU Pharmacology and Anaesthesia', 'A patient receiving cyclosporine post-transplant has hypertension. Which drug is CONTRAINDICATED?', '["Verapamil", "Lisinopril", "Amlodipine", "Nifedipine"]'::jsonb, 0, 'Verapamil increases cyclosporine levels via CYP3A4 inhibition, risking toxicity.', 'ICU Pharmacology'),
(144, 'ICU Pharmacology and Anaesthesia', 'A nurse mistakenly calculates a dopamine infusion using the patient''s weight in pounds (80 lb) instead of converting to kilograms (36.4 kg) first. If the ordered dose is 5 mcg/kg/min with a concentration of 1600 mcg/mL, by roughly what factor will the error inflate the calculated rate compared to the correct rate?', '["Approximately 2.2 times too high", "Approximately 10 times too high", "No difference, the rate is unaffected", "Approximately half the correct rate"]'::jsonb, 0, 'Using pounds instead of kilograms without conversion means the ''weight'' value used is 2.2 times larger than the true kilogram value, so the calculated mcg/min dose (and resulting rate) becomes approximately 2.2 times too high — a dangerous overdose.', 'ICU Pharmacology'),
(145, 'ICU Pharmacology and Anaesthesia', 'The nurse is caring for a patient on a continuous sedative infusion. The nurse should be aware that which of the following is a major complication of prolonged sedation?', '["A decreased need for mechanical ventilation", "Delirium and an increased length of stay in the ICU", "Increased mobility and decreased risk of pressure ulcers", "An increased level of consciousness"]'::jsonb, 1, 'Prolonged sedation can lead to a number of negative consequences, including delirium, an increased length of stay, and an increased risk of long-term cognitive impairment. The goal is to use the least amount of sedation necessary to keep the patient comfortable and safe.', 'ICU Pharmacology'),
(146, 'ICU Pharmacology and Anaesthesia', 'A nurse is managing the pain of a patient who is sedated. The nurse knows that the most effective way to assess a sedated patient''s pain is by:', '["Assessing the patient''s heart rate and blood pressure", "Assuming the patient is not in pain since they are sedated", "Using a behavioral pain scale, such as the BPS or CPOT", "Asking the patient to rate their pain on a scale of 1-10"]'::jsonb, 2, 'A sedated patient cannot verbally communicate their pain. The nurse must use a validated behavioral pain scale, such as the Behavioral Pain Scale (BPS) or the Critical-Care Pain Observation Tool (CPOT), which assesses non-verbal signs of pain like facial expressions and body movements.', 'ICU Pharmacology'),
(147, 'ICU Pharmacology and Anaesthesia', 'Which action should the nurse take when preparing patient-controlled analgesia for a postoperative patient?', '["Ask another nurse to double-check the setup before patient use.", "Caution the patient to limit the number of times he presses the dosing button.", "Provide clear, simple instructions for dosing if the patient is cognitively impaired", "Instruct the patient to administer a dose only when experiencing pain."]'::jsonb, 0, 'Having a second nurse double-check PCA setup is a core safety practice before patient use.', 'ICU Pharmacology'),
(148, 'ICU Pharmacology and Anaesthesia', 'What is the antidote for a cholinergic crisis caused by anticholinesterase medication overdose?', '["Flumazenil", "Naloxone", "Atropine", "Protamine sulfate"]'::jsonb, 2, 'Atropine, an anticholinergic agent, is used to counteract the excessive muscarinic effects of a cholinergic crisis caused by anticholinesterase overdose.', 'ICU Pharmacology'),
(149, 'ICU Pharmacology and Anaesthesia', 'A patient on warfarin has an INR of 8.0. Which reversal agent is used for active bleeding?', '["Vitamin K IV", "FFP", "Protamine sulfate", "Andexanet alfa"]'::jsonb, 1, 'FFP provides immediate clotting factors for warfarin reversal. Vitamin K works slowly.', 'ICU Pharmacology'),
(150, 'ICU Pharmacology and Anaesthesia', 'A nurse is monitoring a sedated patient in the ICU using the Richmond Agitation-Sedation Scale (RASS). A score of 0 on the RASS indicates:', '["Unarousable", "Alert and calm", "Agitated or restless", "Light sedation"]'::jsonb, 1, 'The RASS score ranges from -5 (unarousable) to +4 (combative). A score of 0 signifies a patient who is alert, calm, and able to interact appropriately. The other options correspond to different scores on the scale.', 'ICU Pharmacology'),
(151, 'ICU Pharmacology and Anaesthesia', 'What is the first-line antidote for suspected opioid overdose causing respiratory depression?', '["Naloxone", "N-acetylcysteine", "Atropine", "Flumazenil"]'::jsonb, 0, 'Naloxone is a competitive opioid receptor antagonist that rapidly reverses opioid-induced respiratory and CNS depression.', 'ICU Pharmacology'),
(152, 'ICU Pharmacology and Anaesthesia', 'Clinically significant carbon monoxide production within an anaesthesia circuit is most associated with which agent reacting with desiccated (dried-out) CO2 absorbent?', '["Desflurane", "Sevoflurane", "Propofol", "Oxygen alone"]'::jsonb, 0, 'Desflurane (and to a lesser extent isoflurane) can react with desiccated absorbent, particularly older barium hydroxide lime, to generate carbon monoxide; keeping absorbent adequately hydrated and changed regularly minimizes this risk.', 'ICU Pharmacology'),
(153, 'ICU Pharmacology and Anaesthesia', 'The oxygen flush valve on an anaesthesia machine delivers pure oxygen directly to the common gas outlet, bypassing the vaporizer, at a flow rate of approximately:', '["1-2 L/min", "100-150 L/min", "5-10 L/min", "35-75 L/min"]'::jsonb, 3, 'The oxygen flush valve delivers oxygen at roughly 35-75 L/min directly from the oxygen supply, bypassing the vaporizers, and should never be activated while the patient is connected to the circuit under positive pressure to avoid barotrauma.', 'ICU Pharmacology'),
(154, 'ICU Pharmacology and Anaesthesia', 'A commonly used first-line antiemetic for postoperative nausea and vomiting prophylaxis is:', '["Atropine", "Morphine", "Succinylcholine", "Ondansetron"]'::jsonb, 3, 'Ondansetron, a 5-HT3 receptor antagonist, is a standard first-line agent for prevention and treatment of postoperative nausea and vomiting.', 'ICU Pharmacology'),
(155, 'ICU Pharmacology and Anaesthesia', 'Compound A, a potentially nephrotoxic breakdown product identified in animal studies, forms when which agent is used with low fresh gas flows and desiccated CO2 absorbent?', '["Isoflurane", "Desflurane", "Sevoflurane", "Nitrous oxide"]'::jsonb, 2, 'Sevoflurane degrades in contact with CO2 absorbents (particularly desiccated ones) to form Compound A, which has raised nephrotoxicity concerns at high concentrations and low fresh gas flows.', 'ICU Pharmacology'),
(156, 'ICU Pharmacology and Anaesthesia', 'During adult cardiac arrest, IV adrenaline (epinephrine) is administered at what dose and interval?', '["0.1mg every 1 minute", "1mg every 3–5 minutes", "1mg every 15 minutes", "10mg once only"]'::jsonb, 1, 'Standard ACLS dosing is 1mg IV adrenaline every 3–5 minutes during cardiac arrest resuscitation.', 'ICU Pharmacology'),
(157, 'ICU Pharmacology and Anaesthesia', 'Noradrenaline has leaked from a peripheral IV into the tissues. The specific treatment is:', '["Applying heat and massaging the area", "Giving IV furosemide", "Local infiltration with phentolamine", "Local injection of more noradrenaline"]'::jsonb, 2, 'Stop the infusion, leave the cannula to aspirate, elevate the limb and give through a central line.', 'ICU Pharmacology'),
(158, 'ICU Pharmacology and Anaesthesia', 'Flushing and rash on the upper body during IV vancomycin is best managed by:', '["Giving it as an IV push", "Doubling the dose", "Slowing the infusion rate", "Stopping all antibiotics permanently"]'::jsonb, 2, 'This ''red man'' reaction is histamine release, not true allergy. Also monitor levels and kidney function.', 'ICU Pharmacology'),
(159, 'ICU Pharmacology and Anaesthesia', 'Dexmedetomidine is useful in ICU because it:', '["Is a long-acting opioid analgesic", "Has no effect on heart rate", "Sedates with little respiratory depression", "Causes deep amnesia and apnoea"]'::jsonb, 2, 'It is an alpha-2 agonist. Side effects include bradycardia and hypotension.', 'ICU Pharmacology'),
(160, 'ICU Pharmacology and Anaesthesia', 'Ketamine is useful for induction in a shocked asthmatic patient because it:', '["Has no effect on airway reflexes", "Maintains blood pressure and causes bronchodilation", "Lowers BP and causes bronchospasm", "Reverses opioid-induced breathing problems"]'::jsonb, 1, 'It is an NMDA antagonist. Emergence reactions are common in adults.', 'ICU Pharmacology'),
(161, 'ICU Management, Ethics and Law', 'Which of the following is a commonly recognized high-risk category for nurses in clinical practice?', '["Correctly documenting a normal vital sign", "Medication administration errors", "Attending a staff meeting", "Taking an approved lunch break"]'::jsonb, 1, 'Medication errors are one of the most frequently cited high-risk categories in nursing practice.', 'Ethics, Law & Management'),
(162, 'ICU Management, Ethics and Law', 'A critically-ill patient has a "Living Will" in the chart. The patient''s condition has deteriorated, but the spouse wants "everything done" regardless of the patient''s wishes. Which ethical principle is the spouse violating?', '["Autonomy", "Beneficence", "Non-maleficence", "Justice"]'::jsonb, 0, 'Overriding a patient''s documented wishes (Living Will) disregards their autonomy.', 'Ethics, Law & Management'),
(163, 'ICU Management, Ethics and Law', 'The nurse manager wants to assess the compliance of staff with a new hand hygiene protocol. Which type of audit would be most effective for this purpose?', '["Retrospective audit", "Outcome audit", "Chart audit", "Concurrent audit"]'::jsonb, 3, 'A concurrent audit would be the most effective as it would allow the manager to observe the nurses'' hand hygiene practices in real-time, providing immediate feedback and a direct measure of compliance with the new protocol.', 'Ethics, Law & Management'),
(164, 'ICU Management, Ethics and Law', 'Documentation of hourly neurological observations for a patient with a head injury is an example of which type of standard in the Donabedian model?', '["Structure", "Outcome", "Input", "Process"]'::jsonb, 3, 'Process standards concern the actual activities carried out during care delivery, such as performing and recording assessments.', 'Ethics, Law & Management'),
(165, 'ICU Management, Ethics and Law', 'Which ethical principle refers to a patient''s right to make their own healthcare decisions?', '["Non-maleficence", "Autonomy", "Justice", "Beneficence"]'::jsonb, 1, 'Autonomy is the ethical principle recognising a competent patient''s right to self-determination in healthcare decisions.', 'Ethics, Law & Management'),
(166, 'ICU Management, Ethics and Law', 'Which of the following organizations requires a mechanism for addressing ethical issues?', '["The Joint Commission", "American Hospital Association", "American Association of Critical-Care Nurses", "Society of Critical Care Medicine"]'::jsonb, 0, 'The Joint Commission requires healthcare organisations to have a mechanism for addressing ethical issues.', 'Ethics, Law & Management'),
(167, 'ICU Management, Ethics and Law', 'An effective handover should be:', '["Conducted without documentation", "Brief but comprehensive", "Based on assumptions", "Done only when convenient"]'::jsonb, 1, 'An effective handover conveys all necessary information concisely without unnecessary detail.', 'Ethics, Law & Management'),
(168, 'ICU Management, Ethics and Law', 'Which of the following is ethical issue during CPR:', '["Refusal and discontinuation of treatment", "Family presence during CPR", "Consent for Treatment", "Trained healthcare providers"]'::jsonb, 1, 'Family presence during resuscitation is one of the most debated ethical issues in critical care.', 'Ethics, Law & Management'),
(169, 'ICU Management, Ethics and Law', 'The process of attracting qualified persons to apply for jobs that are open is referred to as:', '["Training", "Recruitment", "Transfer", "Human resource management"]'::jsonb, 1, 'Recruitment is attracting qualified people to apply for vacant jobs. Selection then picks the best applicant.', 'Ethics, Law & Management'),
(170, 'ICU Management, Ethics and Law', 'Which ethical principle is demonstrated by respecting a competent patient''s informed refusal of treatment?', '["Justice", "Fidelity", "Autonomy", "Beneficence"]'::jsonb, 2, 'Respecting a competent patient''s informed refusal of treatment reflects the ethical principle of autonomy.', 'Ethics, Law & Management'),
(171, 'ICU Management, Ethics and Law', 'It is a specially staffed and equipped area of a hospital that provides a level of care intermediate between intensive care and general ward care. The critical care nurse knows this is:', '["Critical care unit", "General ward", "Post anaesthesia recovery unit", "High dependency unit"]'::jsonb, 3, 'An intermediate level of care between ICU and general ward defines a High Dependency Unit.', 'Ethics, Law & Management'),
(172, 'ICU Management, Ethics and Law', 'A family that does not know the patient''s end-of-life wishes assumes they know what is best for the patient. This reflects:', '["Veracity", "Pragmatism", "Justice", "Paternalism"]'::jsonb, 3, 'Paternalism is others deciding what is "best" for a patient without knowing or respecting the patient''s own wishes.', 'Ethics, Law & Management'),
(173, 'ICU Management, Ethics and Law', 'In functional nursing, care is organized according to:', '["Bed numbers", "Nursing tasks", "Family preference", "Patient diagnosis"]'::jsonb, 1, 'Functional nursing organises care delivery around specific tasks rather than the whole patient.', 'Ethics, Law & Management'),
(174, 'ICU Management, Ethics and Law', 'Discipline, as part of the Controlling function of management, should ideally be:', '["Used only as a first response before any coaching or feedback", "Fair, consistent, and applied according to established policy", "Avoided entirely regardless of the situation", "Applied inconsistently depending on personal relationships"]'::jsonb, 1, 'Effective disciplinary practice is fair, consistent and policy-based, typically following a progressive approach rather than being the very first response to an issue.', 'Ethics, Law & Management'),
(175, 'ICU Management, Ethics and Law', 'A nursing audit reveals that many nurses are not completing the required pain assessment documentation. The next step in quality assurance should be to:', '["Punish the nurses who failed to document", "Change the pain assessment policy", "Tell the patients to complain if their pain is not assessed", "Provide a refresher course on pain assessment and documentation"]'::jsonb, 3, 'A lack of proper documentation suggests a need for education or a review of the process. Providing a refresher course is a constructive approach to improving practice and ensuring compliance with the hospital''s standards.', 'Ethics, Law & Management'),
(176, 'ICU Management, Ethics and Law', 'A ward patient''s NEWS2 score is 7. The ICU outreach nurse expects:', '["Routine 12-hourly observations on the ward", "No change, as this score is in the normal range", "An emergency response by a critical care team", "Discharge home later that same evening"]'::jsonb, 2, 'A score of 7 or more is a high clinical risk.', 'Ethics, Law & Management'),
(177, 'ICU Management, Ethics and Law', 'When one ICU bed is free and two patients need it, the bed should go to the patient who:', '["Is most likely to benefit from ICU care", "Can pay for the ICU bed in cash today", "Has the highest social status in the town", "Arrived at the hospital first that day"]'::jsonb, 0, 'Use clear admission criteria and document the decision.', 'Ethics, Law & Management'),
(178, 'ICU Management, Ethics and Law', 'Which practice best reduces burnout and moral distress in ICU nurses?', '["Removing all staff rotation", "Banning staff from discussing deaths", "Regular team debriefing after critical events", "Longer shifts without breaks"]'::jsonb, 2, 'Support, workload control and clinical supervision also help.', 'Ethics, Law & Management'),
(179, 'ICU Management, Ethics and Law', 'Discharging patients from ICU at night is discouraged mainly because it is linked to:', '["Better sleep for the patient", "A lower nursing workload overnight", "Lower overall hospital costs", "Higher readmission and mortality"]'::jsonb, 3, 'Plan discharges in the daytime with a full handover to the ward.', 'Ethics, Law & Management'),
(180, 'ICU Management, Ethics and Law', 'Three ICU patients develop the same resistant organism within a week. The manager''s first step is to:', '["Wait for more cases before taking any action", "Inform infection control and cohort or isolate the patients", "Stop the hand hygiene audits to save time", "Close the whole hospital to new admissions"]'::jsonb, 1, 'Then review practices, screen contacts and reinforce hand hygiene and cleaning.', 'Ethics, Law & Management'),
(181, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which of the following is a risk associated with the use of portable tablets for documentation in a busy clinical setting?', '["They require constant access to a wired internet connection", "The tablets are too heavy for nurses to carry", "The tablet screen is too small to view information", "They are susceptible to being lost, stolen, or damaged"]'::jsonb, 3, 'Due to their portability, tablets and other mobile devices have a higher risk of being misplaced or stolen. This poses a significant data security risk, as a stolen device could contain sensitive patient health information.', 'Research & Nursing Process'),
(182, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'In research study where the researcher present what he hopes to achieve at the end of study will be expressed under:', '["Statement of the problem", "Aims/purpose of the study", "Objectives of the study", "Background of the study"]'::jsonb, 1, 'The aims or purpose state what the researcher hopes to achieve by the end of the study.', 'Research & Nursing Process'),
(183, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which of the following is a procedure that enables the researcher to organise, interpret, and communicate numerical information?', '["Statistics", "Descriptive", "Inferential", "Means"]'::jsonb, 0, 'Statistics is the set of procedures for organising, summarising, interpreting and communicating numerical data.', 'Research & Nursing Process'),
(184, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which nursing diagnosis format is used when the nurse suspects a problem may exist but needs additional data to confirm or rule it out?', '["Possible diagnosis", "Actual diagnosis", "Syndrome diagnosis", "Wellness diagnosis"]'::jsonb, 0, 'A possible nursing diagnosis is used when available data suggest a problem may exist, but further data collection is needed to confirm or rule it out.', 'Research & Nursing Process'),
(185, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A nurse made Mr Kay''s care plan on admission on Tuesday, then made another care plan for him on Wednesday''s shift. Wednesday''s plan is a(n):', '["Reviewed plan", "Initial plan", "Ongoing plan", "Discharge plan"]'::jsonb, 2, 'The initial plan is made on admission. Plans updated on later shifts as the patient''s status changes are ongoing plans.', 'Research & Nursing Process'),
(186, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The New York Heart Association (NYHA) functional classification (Class I-IV) for heart failure severity is an example of which scale of measurement?', '["Ordinal scale", "Ratio scale", "Interval scale", "Nominal scale"]'::jsonb, 0, 'NYHA class ranks increasing severity of symptoms in order, but the classes do not represent equal, measurable intervals, so it is ordinal.', 'Research & Nursing Process'),
(187, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which step of the research process involves condensing raw data into tables, charts, and summary statistics to make it more understandable?', '["Literature review", "Problem identification", "Formulation of research questions", "Organisation and analysis of data"]'::jsonb, 3, 'Organizing and analyzing data involves reducing and summarizing raw data into a manageable, interpretable form such as tables and charts.', 'Research & Nursing Process'),
(188, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Mr john a post-operative patient in ICU developed a severe fever 4 days after the surgery, this is typical of:', '["Primary infection", "Secondary infection", "Malnutrition", "Normal surgical process"]'::jsonb, 1, 'A new fever appearing several days after surgery (not immediately) suggests a secondary (hospital-acquired) infection.', 'Research & Nursing Process'),
(189, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The guiding clinical principle for choosing between enteral and parenteral nutrition in a critically ill patient is best summarized as:', '["Parenteral nutrition should always be used first regardless of GI function", "Enteral and parenteral nutrition are equally preferred with no clinical rationale for choosing one over the other", "Oral intake should always be attempted before any tube feeding is considered, regardless of aspiration risk", "\"If the gut works, use it\" — enteral nutrition is preferred whenever the GI tract is functional"]'::jsonb, 3, 'The core principle of nutrition support is that enteral feeding should be used whenever the gastrointestinal tract is functional, because it is safer, more physiologic, and less costly than parenteral nutrition.', 'Research & Nursing Process'),
(190, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'A pleural effusion typically becomes visible on a standard chest X-ray only once fluid volume reaches approximately:', '["2–3 litres", "150–300ml", "5–10ml", "There is no minimum volume — any amount is visible"]'::jsonb, 1, 'A pleural effusion generally needs to reach roughly 150–300ml before it becomes detectable on a standard chest X-ray.', 'Research & Nursing Process'),
(191, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', '---------------- is a standard healthcare practice that helps prevent the transfer of germs to or from an open wound and other susceptible areas on a patient''s body.', '["Clean Technique", "Sterile Technique", "Aseptic Technique", "Asepitic Technique"]'::jsonb, 2, 'Aseptic technique is the standard practice preventing germ transfer to/from open wounds.', 'Research & Nursing Process'),
(192, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which insertion site for a central venous catheter is generally associated with the LOWEST risk of catheter-related bloodstream infection?', '["Internal jugular vein with a dressing changed daily", "Any site is equally low-risk once inserted", "Femoral vein", "Subclavian vein"]'::jsonb, 3, 'The subclavian site is associated with a lower infection risk compared with the femoral or internal jugular sites, which is why it is often preferred for longer-term central access when feasible.', 'Research & Nursing Process'),
(193, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which type of nursing diagnosis describes a problem that is currently present and validated by the existence of defining characteristics (signs and symptoms)?', '["Actual nursing diagnosis", "Risk nursing diagnosis", "Health promotion diagnosis", "Possible nursing diagnosis"]'::jsonb, 0, 'An actual nursing diagnosis describes a problem that currently exists, confirmed by the presence of defining characteristics (signs and symptoms).', 'Research & Nursing Process'),
(194, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'During electronic health documentation, which computer part allows a critical care nurse to enter patient data?', '["Input device", "Software", "Operating system", "Output device"]'::jsonb, 0, 'Input devices (keyboard, mouse, touchscreen, scanner) put data into the computer. Output devices (monitor, printer) display it.', 'Research & Nursing Process'),
(195, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The Glasgow Coma Scale (GCS) score, which ranks a patient''s level of consciousness from 3 to 15, is best classified as which scale of measurement?', '["Ratio", "Interval", "Nominal", "Ordinal"]'::jsonb, 3, 'The GCS ranks levels of consciousness in order, but the difference between successive scores does not represent an equal clinical interval, making it an ordinal scale.', 'Research & Nursing Process'),
(196, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'For a patient expected to need enteral tube feeding for only 2-3 weeks, the most appropriate feeding access is:', '["A short-term nasogastric or orogastric tube", "A percutaneous endoscopic gastrostomy (PEG) tube", "Total parenteral nutrition", "A surgically placed jejunostomy"]'::jsonb, 0, 'Short-term nasogastric or orogastric tubes are appropriate when enteral access is needed for less than approximately 4 weeks; longer-term needs are better served by a gastrostomy or jejunostomy.', 'Research & Nursing Process'),
(197, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The ideal tip position for a central venous catheter is:', '["Deep in the right ventricle near the apex", "The lower superior vena cava at the cavo-atrial junction", "In the left atrium across the septum", "In the internal jugular vein near the jaw"]'::jsonb, 1, 'Check the post-insertion X-ray also for pneumothorax.', 'Research & Nursing Process'),
(198, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'The recommended bedside check of nasogastric tube position before feeding is:', '["Placing the tube end in water to look for bubbles", "Patient comfort with no coughing", "The ''whoosh'' test with air and a stethoscope", "Aspirate pH of 5.5 or below"]'::jsonb, 3, 'If pH is above 5.5 or no aspirate is obtained, confirm with X-ray. The whoosh test is unreliable.', 'Research & Nursing Process'),
(199, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'Which is one of the WHO ''five moments'' for hand hygiene?', '["Only after removing gloves at home", "Only at the start of the shift", "Before entering the hospital car park", "Before an aseptic or clean procedure"]'::jsonb, 3, 'The others: before touching a patient, after body fluid exposure, after touching a patient and after touching their surroundings.', 'Research & Nursing Process'),
(200, 'Research, Nursing Process, ICT, Infection Control, Lab, Radiology and Rehabilitation', 'After a needlestick injury from a patient with HIV, the nurse should first wash the wound, report it, and start post-exposure prophylaxis:', '["Only after 1 week, if symptoms of infection appear", "Only if the source patient agrees to it", "Only after their own HIV test comes back positive", "As soon as possible, ideally within hours and no later than 72 hours"]'::jsonb, 3, 'Encourage bleeding; do not scrub or suck the wound.', 'Research & Nursing Process');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
